// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{})
}

type ChiServerOptions struct {
	BaseURL          string
	BaseRouter       chi.Router
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, r chi.Router) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseRouter: r,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, r chi.Router, baseURL string) http.Handler {
	return HandlerWithOptions(si, ChiServerOptions{
		BaseURL:    baseURL,
		BaseRouter: r,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options ChiServerOptions) http.Handler {
	r := options.BaseRouter

	if r == nil {
		r = chi.NewRouter()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/dataflow/graph", wrapper.DataflowGetGraph)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/dataflow/graph/export", wrapper.DataflowExportGraph)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/dataflow/report", wrapper.DataflowGetReport)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/dataflow/snapshots", wrapper.DataflowListSnapshots)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/dataflow/snapshots", wrapper.DataflowPublishSnapshot)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/dataflow/snapshots/{id}", wrapper.DataflowGetSnapshot)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/dataflow/layout", wrapper.DataflowGetLayout)
	})
	r.Group(func(r chi.Router) {
		r.Put(options.BaseURL+"/admin/v1/dataflow/layout", wrapper.DataflowSaveLayout)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/dataflow/layout/reset", wrapper.DataflowResetLayout)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/dataflow/discovery-scans", wrapper.DataflowListDiscoveryScans)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/dataflow/discovery-scans", wrapper.DataflowRunDiscoveryScan)
	})
	r.Group(func(r chi.Router) {
		r.Get(options.BaseURL+"/admin/v1/dataflow/discovery-scans/{id}/findings", wrapper.DataflowListDiscoveryFindings)
	})
	r.Group(func(r chi.Router) {
		r.Post(options.BaseURL+"/admin/v1/dataflow/discovery-findings/{id}/review", wrapper.DataflowReviewDiscoveryFinding)
	})

	return r
}

